<script>
const EPSILON_CHARACTER = 'ε';
const RESERVED_SYMBOLS = [EPSILON_CHARACTER, '$', '#', '@', 'λ'];

export default {
  props: {
    grammar: {
      required: true,
      type: Object,
      default: () => ({
        terminals: [],
        nonTerminals: [],
        rules: [],
        startSymbol: null
      })
    }
  },
  data() {
    return {
      errorMessage: '',
      newTerminalInput: '',
      newNonTerminalInput: '',
      newRuleLeft: null,
      newRuleRight: '',
      newRuleIsEmpty: false
    }
  },
  computed: {
    allowedRightSymbols() {
      return [...this.grammar.terminals, ...this.grammar.nonTerminals];
    }
  },
  methods: {
    addTerminalSymbol() {
      const symbol = this.newTerminalInput.trim();
      if (!this._validateSymbol(symbol)) return;
      if (this._isSymbolInAnyAlphabet(symbol)) {
        this._showError(`Символ "${symbol}" уже используется`);
        return;
      }
      this.grammar.terminals.push(symbol);
      this.newTerminalInput = '';
      this.errorMessage = '';
    },

    addNonTerminalSymbol() {
      const symbol = this.newNonTerminalInput.trim();
      if (!this._validateSymbol(symbol)) return;
      if (this._isSymbolInAnyAlphabet(symbol)) {
        this._showError(`Символ "${symbol}" уже используется`);
        return;
      }
      this.grammar.nonTerminals.push(symbol);
      this.newNonTerminalInput = '';
      this.errorMessage = '';
    },

    removeSymbol(arrayName, index) {
      const symbolToRemove = this.grammar[arrayName][index];
      if (this.grammar.startSymbol === symbolToRemove) this.grammar.startSymbol = null;
      this.grammar[arrayName].splice(index, 1);

      this.grammar.rules = this.grammar.rules.filter(
        r => r.left !== symbolToRemove && !r.right.includes(symbolToRemove)
      );
    },

    _validateSymbol(symbol) {
      if (!symbol) { this._showError('Символ не введен.'); return false; }
      if (RESERVED_SYMBOLS.includes(symbol)) { this._showError(`Символ "${symbol}" зарезервирован`); return false; }
      if (symbol.length > 1) { this._showError('Символ должен быть одним знаком'); return false; }
      if (!/^[A-Za-zА-Яа-я0-9α-ωΑ-Ω_\-':;]$/.test(symbol)) { this._showError(`Символ "${symbol}" недопустим`); return false; }
      return true;
    },

    _isSymbolInAnyAlphabet(symbol) {
      return this.grammar.terminals.includes(symbol) || this.grammar.nonTerminals.includes(symbol);
    },

    _showError(message) { this.errorMessage = message; },

    clearAllSymbols() {
      this.grammar.terminals = [];
      this.grammar.nonTerminals = [];
      this.grammar.rules = [];
      this.grammar.startSymbol = null;
      this.errorMessage = '';
      this.newTerminalInput = '';
      this.newNonTerminalInput = '';
      this.newRuleLeft = null;
      this.newRuleRight = '';
      this.newRuleIsEmpty = false;
    },

    addRule() {
      if (!this.newRuleLeft) {
        this._showError('Выберите левую часть правила');
        return;
      }

      let right = this.newRuleIsEmpty ? '' : this.newRuleRight.trim();

      if (right === '' && !this.newRuleIsEmpty) {
        this._showError('Правая часть правила не может быть пустой');
        return;
      }

      for (const ch of right) {
        if (!this.allowedRightSymbols.includes(ch) && ch !== EPSILON_CHARACTER) {
          this._showError(`Символ "${ch}" не разрешён в правой части`);
          return;
        }
      }

      const exists = this.grammar.rules.some(r => r.left === this.newRuleLeft && r.right === right);
      if (exists) {
        this._showError(`Правило "${this.newRuleLeft} → ${right}" уже существует`);
        return;
      }

      this.grammar.rules.push({ left: this.newRuleLeft, right });
      this.newRuleRight = '';
      this.newRuleIsEmpty = false;
      this.errorMessage = '';
    },

    removeRule(index) {
      this.grammar.rules.splice(index, 1);
    },

    onEmptyRuleToggle() {
      if (this.newRuleIsEmpty) {
        this.newRuleRight = EPSILON_CHARACTER;
      } else {
        this.newRuleRight = '';
      }
    },

    onRuleRightInput(event) {
      const input = event.target.value;
      const filtered = Array.from(input)
        .filter(ch => this.allowedRightSymbols.includes(ch));
      this.newRuleRight = filtered.join('');
    }
  }
}
</script>

<template>
  <div class="grammar-editor">
    <div v-if="errorMessage" class="error-message">{{ errorMessage }}</div>

    <!-- Терминалы -->
    <div class="symbols-section">
      <h3>Терминальные символы ({{ grammar.terminals.length }})</h3>
      <div class="input-group">
        <input v-model="newTerminalInput" type="text" maxlength="1" @keyup.enter="addTerminalSymbol" placeholder="a" />
        <button @click="addTerminalSymbol" class="btn-add" title="Добавить терминал">+</button>
      </div>
      <div v-if="grammar.terminals.length > 0" class="symbols-list">
        <div v-for="(symbol, idx) in grammar.terminals" :key="'t-' + idx" class="symbol-item">
          <span class="symbol-text">{{ symbol }}</span>
          <button @click="removeSymbol('terminals', idx)" class="btn-remove" title="Удалить">×</button>
        </div>
      </div>
      <div v-else class="empty-state">Терминальные символы не добавлены</div>
    </div>

    <!-- Нетерминалы -->
    <div class="symbols-section">
      <h3>Нетерминальные символы ({{ grammar.nonTerminals.length }})</h3>
      <div class="input-group">
        <input v-model="newNonTerminalInput" type="text" maxlength="1" @keyup.enter="addNonTerminalSymbol" placeholder="S" />
        <button @click="addNonTerminalSymbol" class="btn-add" title="Добавить нетерминал">+</button>
      </div>
      <div v-if="grammar.nonTerminals.length > 0" class="symbols-list">
        <div v-for="(symbol, idx) in grammar.nonTerminals" :key="'nt-' + idx" class="symbol-item">
          <span class="symbol-text">{{ symbol }}</span>
          <button @click="removeSymbol('nonTerminals', idx)" class="btn-remove" title="Удалить">×</button>
        </div>
      </div>
      <div v-else class="empty-state">Нетерминальные символы не добавлены</div>
    </div>

    <!-- Правила -->
    <div class="symbols-section">
      <h3>Правила ({{ grammar.rules.length }})</h3>
      <div class="input-group rule-input">
        <select v-model="newRuleLeft" class="left-select">
          <option :value="null" disabled>Выберите</option>
          <option v-for="nt in grammar.nonTerminals" :key="nt" :value="nt">{{ nt }}</option>
        </select>

        <span class="rule-arrow">→</span>

        <input v-model="newRuleRight" type="text" :disabled="newRuleIsEmpty" @input="onRuleRightInput" @keyup.enter="addRule" placeholder="abc" />

        <label class="epsilon-label">
          <input type="checkbox" v-model="newRuleIsEmpty" @change="onEmptyRuleToggle" />
          ε-правило
        </label>

        <button @click="addRule" class="btn-add" title="Добавить правило">+</button>
      </div>

      <div v-if="grammar.rules.length > 0" class="symbols-list">
        <div v-for="(rule, idx) in grammar.rules" :key="'rule-' + idx" class="symbol-item">
          <span class="symbol-text">{{ rule.left }} → {{ rule.right }}</span>
          <button @click="removeRule(idx)" class="btn-remove" title="Удалить">×</button>
        </div>
      </div>
      <div v-else class="empty-state">Правила не добавлены</div>
    </div>

    <!-- Аксиома -->
    <div class="symbols-section">
      <h3>Аксиома грамматики</h3>
      <div class="input-group">
        <select v-model="grammar.startSymbol" class="left-select">
          <option :value="null">—</option>
          <option v-for="nt in grammar.nonTerminals" :key="'start-' + nt" :value="nt">{{ nt }}</option>
        </select>
      </div>
      <div v-if="grammar.startSymbol" class="symbol-item large">
        <span class="symbol-text">{{ grammar.startSymbol }}</span>
      </div>
      <div v-else class="empty-state">Аксиома не выбрана</div>
    </div>

    <div class="actions">
      <button @click="clearAllSymbols" class="btn-clear">Очистить всё</button>
    </div>
  </div>
</template>

