<script setup>
import { reactive, ref, computed, nextTick } from 'vue'
import GrammarEditor from './components/GrammarEditor.vue'
import GrammarLatexView from './components/GrammarLatexView.vue'
import LRVisualizer from './components/LRVisualizer.vue'
import AutomataSelector from './components/AutomataSelector.vue'

const grammar = reactive({
  terminals: [],
  nonTerminals: [],
  rules: [],
  startSymbol: null
})

const automatonType = ref('LR0')
const automatonBuilt = ref(false)
const automatonResult = ref(null)

const isGrammarValid = computed(() =>
  grammar.rules.length > 0 &&
  grammar.startSymbol !== null
)

async function buildAutomaton() {
  if (!isGrammarValid.value) return

  const payload = {
    terminals: grammar.terminals,
    nonTerminals: grammar.nonTerminals,
    rules: grammar.rules,
    startSymbol: grammar.startSymbol
  }

  const response = await fetch('/api/build/lr0', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  })

  if (!response.ok) {
    console.error('Ошибка построения автомата')
    return
  }

  automatonResult.value = await response.json()
  automatonBuilt.value = true

  nextTick(() => {
    window.scrollTo({
      top: document.body.scrollHeight,
      behavior: 'smooth'
    })
  })
}
</script>


<template>
  <div class="app">
    <div class="workspace">
      <!-- Левая часть: редактор грамматики -->
      <div class="left-panel">
        <GrammarEditor :grammar="grammar" />
        <GrammarLatexView :grammar="grammar" />
      </div>

      <!-- Правая часть: выбор типа и кнопка построения -->
      <div class="right-panel">
        <AutomataSelector v-model="automatonType" />

        <button @click="buildAutomaton" class="build-button" :disabled="!isGrammarValid"
          :class="{ disabled: !isGrammarValid }">
          <span class="material-symbols-outlined">play_arrow</span>
          Построить автомат
        </button>

        <p v-if="!isGrammarValid" class="hint">
          Заполните грамматику и выберите стартовый символ
        </p>
      </div>
    </div>

    <!-- Визуализатор (появляется после построения) -->
    <div v-if="automatonBuilt" class="visualizer-wrapper">
      <LRVisualizer :build-log="automatonResult?.buildLog || { operations: [] }" />
    </div>
  </div>
</template>

