<script setup>
import { computed } from 'vue'
import MathJax from './MathJax.vue'

const props = defineProps({
    grammar: {
        type: Object,
        required: true
    }
})

/**
 * Tagged template — чтобы LaTeX читался нормально
 */
function latex(strings, ...values) {
    return strings.reduce(
        (acc, s, i) => acc + s + (values[i] ?? ''),
        ''
    )
}

/**
 * Формат множества алфавита:
 * ∅ | { a, b, c }
 */
function formatAlphabetSet(arr) {
    return arr.length
        ? `\\{ ${arr.join(', ')} \\}`
        : '\\varnothing'
}

/**
 * Правая часть правила:
 * ε → \varepsilon
 */
function formatRightPart(right) {
    return right === 'ε' || right === ''
        ? '\\varepsilon'
        : right
}

/**
 * Формат множества правил с альтернативами:
 *
 * A → α | β
 * B → γ
 */
function formatRuleSet(rules) {
    if (!rules.length) {
        return '\\varnothing'
    }

    // группировка по левой части
    const grouped = {}
    for (const { left, right } of rules) {
        if (!grouped[left]) {
            grouped[left] = []
        }
        grouped[left].push(formatRightPart(right))
    }

    // каждая группа — с новой строки
    const lines = Object.entries(grouped).map(
        ([left, rights]) => `${left} \\to ${rights.join(' \\mid ')}`
    )

    return `\\{
${lines.join(', ')}
\\}`
}

const latexCode = computed(() => {
    const G = props.grammar

    return latex`
$$
\\begin{aligned}
G &= (\\Gamma, \\Sigma, P, S) \\\\
\\Gamma &= ${formatAlphabetSet(G.nonTerminals)} \\\\
\\Sigma &= ${formatAlphabetSet(G.terminals)} \\\\
P &= ${formatRuleSet(G.rules)} \\\\
${G.startSymbol ? 'S &= ' + G.startSymbol : ''}
\\end{aligned}
$$
`
})
</script>

<template>
    <MathJax :latex="latexCode" />
</template>
