<script setup>
import { ref, watch, onMounted, nextTick } from 'vue'

const props = defineProps({
  latex: {
    type: String,
    required: true
  }
})

const container = ref(null)

/**
 * Перерендер MathJax
 */
async function typeset() {
  if (!window.MathJax || !container.value) return

  await nextTick()

  // очищаем предыдущий рендер
  container.value.innerHTML = props.latex

  // MathJax v3
  if (window.MathJax.typesetPromise) {
    await window.MathJax.typesetPromise([container.value])
  }
}

onMounted(typeset)

watch(
  () => props.latex,
  () => {
    typeset()
  }
)
</script>

<template>
  <div ref="container" />
</template>