<script setup>
import { ref, markRaw, nextTick, watch } from 'vue'
import { VueFlow, useVueFlow, Controls, Background } from '@braks/vue-flow'
import LRAutomaticState from './LRAutomaticState.vue'
import { useDagreLayout } from './useLayout.ts'

const nodeTypes = {
  lrItem: markRaw(LRAutomaticState)
}

// === Пропсы ===
const props = defineProps({
  buildLog: {
    type: Object,
    required: true
  }
})

// === Реактивные данные ===
const nodes = ref([])
const edges = ref([])
const history = ref([])
const currentStep = ref(-1)
const logs = ref([])

const { fitView } = useVueFlow()
const { layout } = useDagreLayout()

// === Функция для преобразования операций ===
function mapOperation(op) {
  if (!op) return null

  switch (op.name) {
    case 'addState':
      return {
        type: 'addState',
        stateName: op.stateName,
        comment: op.message
      }

    case 'addItem':
      return {
        type: 'addLR0Item',
        stateName: op.state,
        item: {
          rule: op.item.rule,
          separator: op.item.dotIndex
        },
        comment: op.message
      }

    case 'addTransition':
      return {
        type: 'addTransition',
        from: op.from,
        to: op.to,
        label: op.through,
        comment: op.message
      }

    default:
      return {
        type: 'logOnly',
        comment: op?.message ?? `[${op.name}]`
      }
  }
}

// === Watcher с проверкой null ===
watch(
  () => props.buildLog,
  (newLog) => {
    if (!newLog || !newLog.operations || newLog.operations.length === 0) {
      history.value = []
      nodes.value = []
      edges.value = []
      logs.value = []
      return
    }

    history.value = newLog.operations.map(mapOperation).filter(Boolean)
    renderUpTo(history.value.length - 1)
  },
  { immediate: true }
)

// === Layout + fitView ===
function applyLayoutAndFit() {
  if (!nodes.value.length && !edges.value.length) return
  nodes.value = layout(nodes.value, edges.value, 'LR')
  nextTick(() => {
    fitView({ duration: 500 })
  })
}

// === Выполнение действия ===
function executeAction(action) {
  if (!action) return

  switch (action.type) {
    case 'addState':
      if (!nodes.value.find(n => n.id === action.stateName)) {
        nodes.value.push({
          id: action.stateName,
          type: 'lrItem',
          position: { x: 0, y: 0 },
          data: { name: action.stateName, lrItems: [] }
        })
      }
      break

    case 'addLR0Item':
      const node = nodes.value.find(n => n.id === action.stateName)
      if (node && action.item) {
        node.data.lrItems.push({
          rule: action.item.rule,
          separator: action.item.separator
        })
      }
      break

    case 'addTransition':
      const edgeId = `e-${action.from}-${action.to}-${action.label || 'eps'}`
      if (!edges.value.find(e => e.id === edgeId)) {
        edges.value.push({
          id: edgeId,
          source: action.from,
          target: action.to,
          label: action.label || '',
          markerEnd: 'arrowclosed'
        })
      }
      break

    case 'logOnly':
      break
  }

  applyLayoutAndFit()
}

// === Рендер до определённого шага ===
function renderUpTo(stepIndex) {
  if (!history.value || history.value.length === 0) return
  if (stepIndex < -1 || stepIndex >= history.value.length) return

  currentStep.value = stepIndex
  nodes.value = []
  edges.value = []
  logs.value = []

  for (let i = 0; i <= stepIndex; i++) {
    const action = history.value[i]
    executeAction(action)
    logs.value.push({
      id: i + 1,
      step: i + 1,
      text: action.comment
    })
  }

  nextTick(() => {
    const container = document.querySelector('.log-panel .log-content')
    if (container) container.scrollTop = container.scrollHeight
  })
}

// === Навигация ===
function goToStart() { renderUpTo(-1) }
function stepBack() { if (currentStep.value > -1) renderUpTo(currentStep.value - 1) }
function stepForward() { if (currentStep.value < history.value.length - 1) renderUpTo(currentStep.value + 1) }
function goToEnd() { renderUpTo(history.value.length - 1) }
</script>


<template>
  <link rel="stylesheet"
    href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0" />

  <div class="app-container">
    <!-- Граф -->
    <div class="graph-container">
      <!-- Панель навигации -->
      <div class="navigation-panel">
        <button @click="goToStart" class="nav-btn" title="В начало">
          <span class="material-symbols-outlined">first_page</span>
        </button>
        <button @click="stepBack" :disabled="currentStep === -1" class="nav-btn" title="Шаг назад">
          <span class="material-symbols-outlined">chevron_left</span>
        </button>
        <button @click="stepForward" :disabled="currentStep >= history.length - 1" class="nav-btn" title="Шаг вперёд">
          <span class="material-symbols-outlined">chevron_right</span>
        </button>
        <button @click="goToEnd" class="nav-btn" title="В конец">
          <span class="material-symbols-outlined">last_page</span>
        </button>
      </div>

      <VueFlow :nodes="nodes" :edges="edges" :node-types="nodeTypes">
        <Background />
        <Controls :show-zoom="true" :show-fit-view="true" :show-interactive="true" />

        <div class="custom-layout-button">
          <button @click="applyLayoutAndFit" title="Перевыровнять и подогнать камеру">
            <span class="material-symbols-outlined">filter_center_focus</span>
          </button>
        </div>
      </VueFlow>
    </div>

    <div class="log-panel">
      <div class="log-header">
        <span class="material-symbols-outlined">history</span>
        Действия
      </div>
      <div class="log-content">
        <div v-for="entry in logs" :key="entry.id" class="log-entry">
          <span class="log-step">[{{ entry.step }}]</span>
          <span class="log-text">{{ entry.text }}</span>
        </div>
        <div v-if="logs.length === 0" class="log-empty">
          Действия не выполнялись.
        </div>
      </div>
    </div>
  </div>
</template>

